class Solution {
    private int findNodePositionReversed(ListNode currNode, int n) {
        // the tail node will be the 1st node in the reverse sense
        if(currNode.next == null) {
            return 1;
        }
        // using recursion, find the current node's position from the reverse sense
        int currNodePos = findNodePositionReversed(currNode.next, n) + 1;
        // when standing at the n+1 th node (in the reverse sense), delete its next node
        if(n + 1 == currNodePos) {
            currNode.next = currNode.next.next;
        }
        return currNodePos;
    }

    public ListNode removeNthFromEnd(ListNode head, int n) {
        if(findNodePositionReversed(head, n) == n) {
            // delete the head
            head = head.next;
        }
        return head;
    }
}
```

